INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 20, 'theory', 'Квиз: хранилище oVirt');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 20, 0, 'Какой хост в классической схеме имеет право менять метаданные томов (создавать, удалять, расширять тома) в центре данных?', '["Любой хост, который первым взял блокировку файла", "Хост, на котором запущен менеджер", "Единственный хост с ролью Storage Pool Manager", "Все хосты по очереди через менеджер"]', 2, 'Метаданные общие, а хранилище не разрешает конфликты записи, поэтому писатель один: SPM. Его назначает менеджер, а исключительность обеспечивает аренда sanlock.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 20, 1, 'Чем является блочный домен хранилища на уровне LVM?', '["Группой томов, имя которой равно UUID домена", "Одним физическим томом без разметки", "Каталогом на файловой системе ext4", "Единственным логическим томом, внутри которого лежат все диски"]', 0, 'Домен — это группа томов, а служебные области и тома дисков — отдельные логические тома в ней. Диск, как и в файловом домене, не смешивается с другими.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 20, 2, 'Где в блочном домене записана ссылка тома на его родителя в цепочке?', '["В файле .lease рядом с томом", "В области ids домена", "Только в базе данных менеджера", "В теге PU_ логического тома и в метаданных тома"]', 3, 'Тег PU_ хранит идентификатор родителя прямо на логическом томе, а то же значение лежит в слоте тома metadata. Поэтому цепочку можно восстановить и без базы менеджера.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 20, 3, 'Для чего в oVirt используются аренды sanlock?', '["Для шифрования трафика между менеджером и хостом", "Чтобы только один хост в каждый момент владел ролью SPM, томом или машиной", "Для сжатия образов qcow2", "Чтобы определять порядок запуска машин"]', 1, 'Аренда — это запись на общем хранилище, которую владелец продлевает. Если продление прекращается, аренда истекает и ресурс можно отдать другому хосту без риска двойного владения.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 20, 4, 'Что будет при настройках по умолчанию, если свободного места в домене меньше критического порога (5 ГБ)?', '["Домен сам удалит самые старые снимки", "Домен станет доступен только для чтения работающим машинам", "Создавать на нём новые диски и снимки будет нельзя", "Менеджер выключит все машины с дисками на этом домене"]', 2, 'Критический порог блокирует операции, которым нужно новое место. Работающие машины продолжают работать, а удалять что-либо автоматически менеджер не станет.');
